const FONTS = "tiny-keys-fonts";
const MANIFEST = "__manifest";

async function previousCopy() {
  for (const k of await caches.keys()) {
    if (k === VERSION || k === FONTS) continue;
    const c = await caches.open(k), m = await c.match(MANIFEST);
    if (m) return { cache: c, hashes: await m.json() };
  }
  return { cache: null, hashes: {} };
}

self.addEventListener("install", event => {
  event.waitUntil((async () => {
    const cache = await caches.open(VERSION);
    const old = await previousCopy();
    const queue = [...ASSETS];
    const worker = async () => {
      for (let item; (item = queue.shift());) {
        const [path, hash] = item;
        if (old.cache && old.hashes[path] === hash) {
          const kept = await old.cache.match(path);
          if (kept) { await cache.put(path, kept); continue; }
        }
        await cache.add(new Request(path, { cache: "reload" }));
      }
    };
    await Promise.all(Array.from({ length: 6 }, worker));
    await cache.put(MANIFEST, new Response(JSON.stringify(Object.fromEntries(ASSETS))));
    await self.skipWaiting();
  })());
});

self.addEventListener("activate", event => {
  event.waitUntil(
    caches.keys()
      .then(keys => Promise.all(keys.filter(k => k !== VERSION && k !== FONTS).map(k => caches.delete(k))))
      .then(() => self.clients.claim())
  );
});

self.addEventListener("fetch", event => {
  const req = event.request;
  if (req.method !== "GET") return;
  const url = new URL(req.url);

  // Google Fonts: keep a copy so the rounded font works offline too
  if (url.hostname.endsWith("googleapis.com") || url.hostname.endsWith("gstatic.com")) {
    event.respondWith(caches.open(FONTS).then(async cache => {
      const hit = await cache.match(req);
      const fresh = fetch(req).then(res => { cache.put(req, res.clone()); return res; }).catch(() => hit);
      return hit || fresh;
    }));
    return;
  }
  if (url.origin !== location.origin) return;

  // Everything else: saved copy first, the network only for anything not saved yet
  event.respondWith(
    caches.open(VERSION)
      .then(c => c.match(req.mode === "navigate" ? "./" : req, { ignoreSearch: true }))
      .then(hit => hit || caches.match(req.mode === "navigate" ? "./" : req, { ignoreSearch: true }))
      .then(hit => hit || fetch(req))
  );
});
